register('MI_SET_PREFERENCES',preferences,()=>true,'Alt+F12');register('MI_SET_LANGUAGE',languageDialog,()=>true,'Alt+F11');register('MI_SET_CHECK_FOR_UPDATES',async()=>{const remote=await fetch('version.json',{cache:'no-store'}).then(r=>r.json());dialog('Обновления',el('p',{text:remote.version==='0.2.1'?'Установлена последняя опубликованная версия 0.2.1.':'Доступна версия '+remote.version+'. Сохраните работу и обновите страницу.'}),{cancel:null});},()=>true);
register('MI_HELP_CONTENTS',()=>{window.open('reference/Help/English/index.html','_blank','noopener');},()=>true,'F1');register('MI_HELP_HOMEPAGE',()=>window.open('https://github.com/ALEXGREENCH/GreenPixel','_blank','noopener'),()=>true);register('MI_HELP_WHATSNEW',()=>dialog('Что нового',el('p',{text:'0.2: классическая оболочка, страницы, инструменты, слои, фильтры и начальная совместимость форматов. Полное соответствие ещё проверяется; см. docs/parity.json.'}),{cancel:null}),()=>true);register('MI_HELP_ABOUT',()=>dialog('О GreenPixel',el('div',{},[el('h2',{text:'GreenPixel Web'}),el('p',{text:'© 2026 Турбориум · GPL-3.0'}),el('p',{text:'Веб-реализация по мотивам GreenPixel 4.0.3.1. Оригинальные ресурсы: Турбориум; формат GFIE: B. Szalkai.'}),el('p',{class:'dialog-note',text:'Это версия в процессе переноса. Неперенесённые команды отключены; наличие работающей команды ещё не подтверждает пиксельное совпадение алгоритма с оригиналом.'})]),{cancel:null}),()=>true);
$('recent').onclick=recentDialog;$('startup-help').onclick=()=>execute('MI_HELP_CONTENTS');$('show-startup').onchange=e=>{settings.showStartup=e.target.checked;persist();};
$('layer-actions').replaceChildren(...[['MI_LAYERS_NEW','□'],['MI_LAYERS_DELETE','×'],['MI_LAYERS_PROP','▣'],['MI_LAYERS_MERGE_SELECTED','▱']].map(([id,symbol])=>el('button',{class:'layer-action layer-action-'+id,text:'',title:t(id),'aria-label':t(id),onclick:()=>execute(id)})));
$('layers-heading').onclick=()=>{$('layers').hidden=!$('layers').hidden;};$('color-heading').onclick=()=>{$('color-body').hidden=!$('color-body').hidden;};
for(const n of [.0625,.125,.25,.5,1,2,3,4,6,8,12,16,24,32,64])$('zoom').append(el('option',{value:n,text:(n*100)+'%'}));$('zoom').onchange=e=>{fitMode=false;zoom=+e.target.value;renderCanvas();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-command]');if(b)execute(b.dataset.command);if(!e.target.closest('#menubar,#menu-popup')){$('menu-popup').hidden=true;document.querySelectorAll('#menubar .active').forEach(b=>b.classList.remove('active'));}});
document.addEventListener('pointerover',e=>{const title=e.target.closest('[title]')?.title;if(title)notify(title);});
document.addEventListener('keydown',e=>{if($('dialog').open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();space=true;renderCanvas();return;}if(stroke)return;const ctrl=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();let cmd;
 for(const [id,c] of registry){if(!c.shortcut||c.shortcut.includes('/'))continue;const parts=c.shortcut.toLowerCase().split('+'),expected=parts.at(-1)==='del'?'delete':parts.at(-1);if(expected===key&&parts.includes('ctrl')===ctrl&&parts.includes('shift')===e.shiftKey&&parts.includes('alt')===e.altKey){e.preventDefault();execute(id);return;}}
 if(ctrl){cmd=({n:e.shiftKey?'MI_ICON_PAGE_NEW':'MI_FILE_NEW_GRAPHIC',o:'MI_FILE_OPEN',s:e.shiftKey?'MI_FILE_SAVE_AS':'MI_FILE_SAVE',z:e.shiftKey?'MI_EDIT_REDO':'MI_EDIT_UNDO',y:'MI_EDIT_REDO',a:'MI_EDIT_SEL_ALL',d:'MI_EDIT_SEL_NONE',c:'MI_EDIT_COPY',x:'MI_EDIT_CUT',v:'MI_EDIT_PASTE',l:'MI_LAYERS_NEW',delete:'MI_EDIT_DELETE'})[key];}
 else if(key==='escape')cmd='MI_EDIT_SEL_NONE';else if(key==='+')cmd='MI_VIEW_ZOOM_IN';else if(key==='-')cmd='MI_VIEW_ZOOM_OUT';else if(key==='*')cmd='MI_VIEW_100_PERCENT';else if(key==='/')cmd='MI_VIEW_FIT_WINDOW';else if(key==='f1')cmd='MI_HELP_CONTENTS';else if(e.altKey&&key==='f12')cmd='MI_SET_PREFERENCES';else if(e.altKey&&key==='f11')cmd='MI_SET_LANGUAGE';
 if(cmd){e.preventDefault();execute(cmd);return;}
 if(!ctrl&&!e.altKey){const name=toolNames.find(n=>toolKeys[n].toLowerCase()===key);if(name){e.preventDefault();selectTool(name);}if(P()&&['arrowleft','arrowright','arrowup','arrowdown'].includes(key)){e.preventDefault();const dx=key==='arrowleft'?-1:key==='arrowright'?1:0,dy=key==='arrowup'?-1:key==='arrowdown'?1:0;if(P().floating)action('Переместить выделение',()=>{P().floating.x+=dx;P().floating.y+=dy;});else{$('viewport').scrollLeft+=dx*32;$('viewport').scrollTop+=dy*32;}}}
});document.addEventListener('keyup',e=>{if(e.code==='Space'){space=false;renderCanvas();}});window.addEventListener('blur',()=>space=false);
window.addEventListener('beforeunload',e=>{if(!reloading&&docs.some(d=>d.dirty)){e.preventDefault();e.returnValue='';}});
document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault();});document.addEventListener('drop',e=>{if(e.dataTransfer.files.length){e.preventDefault();openFiles(Array.from(e.dataTransfer.files));}});
try{const state=await Store.load('workspace');if(state?.docs?.length){docs=state.docs;active=Math.max(0,Math.min(state.active,docs.length-1));for(const d of docs){history.set(d.id,new M.History());saved.set(d.id,state.saved?.find(([id])=>id===d.id)?.[1]||M.clone(d));}}recent=await Store.load('recent')||[];if(!docs.length){const old=localStorage.getItem('turborium-greenpixel-autosave');if(old){const d=M.parse(old);docs.push(d);active=0;history.set(d.id,new M.History());saved.set(d.id,M.clone(d));}}}catch(error){notify('Восстановление черновика: '+error.message);}
try{swatchColors=decodePalette(await fetch('reference/Swatches/Default.swa').then(r=>r.arrayBuffer()));}catch{}
startup=settings.showStartup||!docs.length;localize();applySettings();renderColor();render();if(!startup){fit();render();}

watchUpdates({hasUnsavedWork:()=>docs.some(d=>d.dirty),allowAutomaticReload:()=>settings.autoUpdate,saveDraft:async()=>{clearTimeout(persistTimer);await Store.save('workspace',{docs,active,saved:[...saved]});await Store.save('recent',recent);reloading=true;}});

// Keep fit-to-window accurate after panel toggles and browser resizing.
let resizeFrame;new ResizeObserver(()=>{cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>{if(fitMode&&P()&&!$('editor').hidden){fit();render();}});}).observe($('viewport'));
addEventListener('resize',()=>{$('menu-popup').hidden=true;document.querySelectorAll('#menubar .active').forEach(b=>b.classList.remove('active'));});
